// Migration: neue Spalten zu bestehender Datenbank hinzufügen
function ensureColumns(PDO $db, string $table, array $cols): void {
    $have = array_column($db->query("PRAGMA table_info($table)")->fetchAll(PDO::FETCH_ASSOC), 'name');
    foreach ($cols as $name => $def) {
        if (!in_array($name, $have, true)) $db->exec("ALTER TABLE $table ADD COLUMN $name $def");
    }
}
ensureColumns($db, 'devices', [
    'vendor' => "TEXT DEFAULT ''", 'info' => "TEXT DEFAULT ''",
    'color'  => "TEXT DEFAULT ''", 'online' => "INTEGER DEFAULT 0",
    'first_seen' => "TEXT DEFAULT ''", 'is_new' => "INTEGER DEFAULT 0",
    'new_since' => "TEXT DEFAULT ''", 'new_reason' => "TEXT DEFAULT ''",
]);
ensureColumns($db, 'vlans', ['last_scan' => "TEXT DEFAULT ''"]);
$db->exec("UPDATE devices SET hostname='' WHERE hostname='Unbekannt (Auto)'");
$db->exec("UPDATE devices SET device_type='' WHERE device_type='Auto-Discovery'");
$db->exec("UPDATE devices SET first_seen=last_seen WHERE IFNULL(first_seen,'')='' AND IFNULL(last_seen,'')<>''");
// Einmalig aufräumen: "MAC geändert"-Markierungen bei Adressen, die schon einen Namen haben, sind überflüssig
$db->exec("UPDATE devices SET is_new=0 WHERE is_new=1 AND new_reason LIKE 'MAC-Adresse ge%' AND (IFNULL(hostname,'')<>'' OR IFNULL(info,'')<>'')");
$db->exec("CREATE INDEX IF NOT EXISTS idx_log_ts ON scan_log(ts)");

// ---------------------------------------------------------------- Helfer
/** Datum als "26.06.2026    22:27 Uhr" (HTML-sicher). */
function fmtDate($s): string {
    $t = $s ? strtotime(is_numeric($s) ? '@' . $s : $s) : false;
    return $t ? date('d.m.Y', $t) . '&nbsp;&nbsp;&nbsp;&nbsp;' . date('H:i', $t) . ' Uhr' : '';
}
/** Datum als Klartext (für title-Attribute). */
function fmtDatePlain($s): string {
    $t = $s ? strtotime(is_numeric($s) ? '@' . $s : $s) : false;
    return $t ? date('d.m.Y H:i', $t) . ' Uhr' : '';
}

function h($s): string { return htmlspecialchars((string)$s, ENT_QUOTES, 'UTF-8'); }

function getSetting(PDO $db, string $k, $default = '') {
    $s = $db->prepare("SELECT v FROM settings WHERE k=?");
    $s->execute([$k]);
    $v = $s->fetchColumn();
    return $v === false ? $default : $v;
}
function setSetting(PDO $db, string $k, $v): void {
    $db->prepare("INSERT INTO settings (k, v) VALUES (?, ?) ON CONFLICT(k) DO UPDATE SET v=excluded.v")->execute([$k, (string)$v]);
}

function shellOk(): bool {
    $disabled = array_map('trim', explode(',', (string)ini_get('disable_functions')));
    return function_exists('shell_exec') && !in_array('shell_exec', $disabled, true);
}

/** "192.168.10.0/24" -> [netzwerk(int), prefix] oder null. Erlaubt /22 bis /30. */
function parseCidr(string $cidr): ?array {
    if (!preg_match('#^(\d{1,3}(?:\.\d{1,3}){3})/(\d{1,2})$#', trim($cidr), $m)) return null;
    $ip = ip2long($m[1]);
    $prefix = (int)$m[2];
    if ($ip === false || $prefix < 22 || $prefix > 30) return null;
    $mask = (-1 << (32 - $prefix)) & 0xFFFFFFFF;
    return [$ip & $mask, $prefix];
}

function vlanHostCount(string $cidr): int {
    $p = parseCidr($cidr);
    return $p ? (1 << (32 - $p[1])) - 2 : 0;
}

/** Alle nutzbaren Host-IPs eines Subnetzes. */
function hostsOf(string $cidr): array {
    $p = parseCidr($cidr);
    if (!$p) return [];
    [$net, $prefix] = $p;
    $ips = [];
    for ($i = $net + 1, $last = $net + (1 << (32 - $prefix)) - 2; $i <= $last; $i++) $ips[] = long2ip($i);
    return $ips;
}

/** Erlaubt Kurzform: "200" wird zu <Netzadresse> + 200, z. B. 192.168.10.200. */
function expandIp(string $v, string $cidr): string {
    $v = trim($v);
    if (preg_match('/^\d{1,3}$/', $v) && ($p = parseCidr($cidr))) return long2ip($p[0] + (int)$v);
    return $v;
}

function isIpInDhcp(string $ip, ?string $start, ?string $end): bool {
    if (!$start || !$end) return false;
    $n = ip2long($ip);
    return $n >= ip2long($start) && $n <= ip2long($end);
}

function normalizeMac(string $mac): string {
    $hex = strtoupper(preg_replace('/[^0-9A-Fa-f]/', '', $mac));
    return strlen($hex) === 12 ? implode(':', str_split($hex, 2)) : trim($mac);
}

function macVendor(string $mac): string {
    static $map = null;
    $hex = strtoupper(preg_replace('/[^0-9A-Fa-f]/', '', $mac));
    if (strlen($hex) < 6) return '';
    if ($map === null) {
        $map = [];
        foreach (OUI_FILES as $f) {
            if (!is_readable($f)) continue;
            foreach (file($f, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES) as $line) {
                if ($line[0] !== '#' && strlen($line) > 7) $map[substr($line, 0, 6)] = trim(substr($line, 7));
            }
            break;
        }
    }
    if (isset($map[substr($hex, 0, 6)])) return $map[substr($hex, 0, 6)];
    // Gesetztes "locally administered"-Bit = zufällige/private MAC (Smartphones, Windows)
    return (hexdec($hex[1]) & 2) ? 'Zufällige MAC (privat)' : '';
}

/** Liest die ARP-Tabelle des Servers: IP => MAC. Funktioniert ohne Root. */
function readArpTable(): array {
    $t = [];
    if (is_readable('/proc/net/arp')) {
        foreach (array_slice(file('/proc/net/arp', FILE_IGNORE_NEW_LINES), 1) as $l) {
            $c = preg_split('/\s+/', trim($l));
            if (count($c) >= 4 && $c[2] !== '0x0' && $c[3] !== '00:00:00:00:00:00') $t[$c[0]] = strtoupper($c[3]);
        }
    }
    if (!$t && shellOk()) {
        $out = (string)shell_exec('ip neigh show 2>/dev/null');
        preg_match_all('/^(\d+\.\d+\.\d+\.\d+) .*lladdr ([0-9a-f:]{17})/im', $out, $m, PREG_SET_ORDER);
        foreach ($m as $x) $t[$x[1]] = strtoupper($x[2]);
    }
    if (!$t && shellOk()) {
        $out = (string)shell_exec('arp -an 2>/dev/null');
        preg_match_all('/\((\d+\.\d+\.\d+\.\d+)\) at ([0-9a-f:]{17})/i', $out, $m, PREG_SET_ORDER);
        foreach ($m as $x) $t[$x[1]] = strtoupper($x[2]);
    }
    return $t;
}

function ouiAvailable(): bool {
    foreach (OUI_FILES as $f) if (is_readable($f)) return true;
    return false;
}

/** Farbbereich zu einer IP (der kleinste passende Bereich gewinnt). $calc = Liste aus ['r'=>..., 's'=>..., 'e'=>...]. */
function rangeFor(int $n, array $calc): ?array {
    foreach ($calc as $x) if ($n >= $x['s'] && $n <= $x['e']) return $x['r'];
    return null;
}

/** Textfarbe für farbige Badges (heller Hintergrund braucht dunkle Schrift). */
function badgeText(string $colorKey): string {
    return in_array($colorKey, ['yellow', 'teal'], true) ? '#212529' : '#ffffff';
}

// ---------------------------------------------------------------- Scan
/** Scannt ein VLAN. Gibt Anzahl aktiver Geräte zurück, -1 bei Fehler. */
function scanVlan(PDO $db, array $vlan): int {
    if (!shellOk()) return -1;
    $xml = shell_exec('nmap -sn -oX - ' . escapeshellarg($vlan['subnet']) . ' 2>/dev/null');
    $sx = $xml ? @simplexml_load_string($xml) : false;
    if (!$sx) return -1;

    $now = date('Y-m-d H:i:s');
    // Neue Clients nur markieren, wenn aktiviert und das VLAN schon einmal gescannt wurde
    // (der allererste Scan eines VLANs ist die Ausgangsbasis, sonst wäre alles "neu").
    $flag = getSetting($db, 'flag_new', '1') === '1' && trim((string)($vlan['last_scan'] ?? '')) !== '';
    $known = [];
    $named = [];   // IPs mit Hostname oder Beschreibung: werden nie (wieder) als "neu" markiert
    foreach ($db->query("SELECT ip, mac, hostname, info FROM devices")->fetchAll(PDO::FETCH_ASSOC) as $r) {
        $known[$r['ip']] = (string)$r['mac'];
        if (trim((string)$r['hostname']) !== '' || trim((string)$r['info']) !== '') $named[$r['ip']] = true;
    }
    $arp = readArpTable();

    $db->beginTransaction();
    $db->prepare("UPDATE devices SET online=0 WHERE vlan_id=?")->execute([$vlan['id']]);
    $ins = $db->prepare("INSERT INTO devices (ip, vlan_id, hostname, mac, vendor, online, last_seen, first_seen, is_new, new_since, new_reason)
        VALUES (?, ?, ?, ?, ?, 1, ?, ?, ?, ?, ?)");
    $upd = $db->prepare("UPDATE devices SET vlan_id=?, online=1, last_seen=?,
        hostname = CASE WHEN IFNULL(hostname,'')='' THEN ? ELSE hostname END,
        mac      = CASE WHEN ?<>'' THEN ? ELSE mac END,
        vendor   = CASE WHEN ?<>'' THEN ? ELSE vendor END,
        first_seen = CASE WHEN IFNULL(first_seen,'')='' THEN ? ELSE first_seen END
        WHERE ip=?");
    $flagStmt = $db->prepare("UPDATE devices SET is_new=1, new_since=?, new_reason=? WHERE ip=?");

    $n = 0;
    $withMac = 0;
    foreach ($sx->host as $host) {
        if ((string)$host->status['state'] !== 'up') continue;
        $ip = $mac = $vendor = '';
        foreach ($host->address as $a) {
            if ((string)$a['addrtype'] === 'ipv4') $ip = (string)$a['addr'];
            elseif ((string)$a['addrtype'] === 'mac') { $mac = (string)$a['addr']; $vendor = (string)$a['vendor']; }
        }
        if ($ip === '') continue;
        if ($mac === '' && isset($arp[$ip])) $mac = $arp[$ip];
        if ($mac !== '') { $mac = normalizeMac($mac); $withMac++; }
        if ($mac !== '' && $vendor === '') $vendor = macVendor($mac);
        $hn = (string)$host->hostnames->hostname['name'];

        if (!array_key_exists($ip, $known)) {
            $ins->execute([$ip, $vlan['id'], $hn, $mac, $vendor, $now, $now, $flag ? 1 : 0, $flag ? $now : '', $flag ? 'Neues Gerät erkannt' : '']);
        } else {
            $upd->execute([$vlan['id'], $now, $hn, $mac, $mac, $mac, $vendor, $now, $ip]);
            if ($flag && !isset($named[$ip]) && $mac !== '' && $known[$ip] !== '' && strcasecmp(normalizeMac($known[$ip]), $mac) !== 0) {
                $flagStmt->execute([$now, 'MAC-Adresse geändert (vorher ' . $known[$ip] . ')', $ip]);
            }
        }
        $n++;
    }

    // Hersteller für vorhandene MACs nachtragen
    $fix = $db->prepare("SELECT ip, mac FROM devices WHERE vlan_id=? AND IFNULL(mac,'')<>'' AND IFNULL(vendor,'')=''");
    $fix->execute([$vlan['id']]);
    $setV = $db->prepare("UPDATE devices SET vendor=? WHERE ip=?");
    foreach ($fix->fetchAll(PDO::FETCH_ASSOC) as $r) $setV->execute([macVendor($r['mac']), $r['ip']]);

    $db->prepare("UPDATE vlans SET last_scan=? WHERE id=?")->execute([$now, $vlan['id']]);
    $db->prepare("INSERT INTO scan_log (vlan_id, ts, online) VALUES (?, ?, ?)")->execute([$vlan['id'], $now, $n]);
    $keep = max(7, (int)getSetting($db, 'log_days', 90));
    $db->prepare("DELETE FROM scan_log WHERE ts < ?")->execute([date('Y-m-d H:i:s', time() - $keep * 86400)]);
    $db->commit();
    $GLOBALS['scanStats'] = ['macs' => $withMac, 'arp' => count($arp)];
    return $n;
}

function scanAll(PDO $db): void {
    set_time_limit(0);
    setSetting($db, 'last_scan_all', time());
    foreach ($db->query("SELECT * FROM vlans")->fetchAll(PDO::FETCH_ASSOC) as $v) scanVlan($db, $v);
    setSetting($db, 'last_scan_all', time());
}

function runDueScan(PDO $db, bool $force = false): bool {
    $interval = (int)getSetting($db, 'scan_interval', 0);
    if (!$force && ($interval <= 0 || time() - (int)getSetting($db, 'last_scan_all', 0) < $interval * 60)) return false;
    scanAll($db);
    return true;
}

// ---------------------------------------------------------------- Statistik
function buildStats(PDO $db): array {
    $vlans  = $db->query("SELECT * FROM vlans ORDER BY vlan_id ASC")->fetchAll(PDO::FETCH_ASSOC);
    $devs   = $db->query("SELECT * FROM devices")->fetchAll(PDO::FETCH_ASSOC);
    $ranges = $db->query("SELECT * FROM ranges")->fetchAll(PDO::FETCH_ASSOC);
    $offlineDays = max(1, (int)getSetting($db, 'offline_days', 30));
    $now = time();

    $byVlan = [];
    foreach ($devs as $d) $byVlan[$d['vlan_id']][] = $d;
    $isDoc = fn($d) => trim((string)$d['hostname']) !== '' || trim((string)$d['info']) !== '' || trim((string)$d['mac']) !== '';

    $S = ['vlans' => [], 'ranges' => [], 'offlineDays' => $offlineDays,
          'tot' => ['vlans' => count($vlans), 'hosts' => 0, 'online' => 0, 'used' => 0, 'new' => 0, 'nodesc' => 0, 'dhcp_size' => 0, 'dhcp_online' => 0, 'devices' => count($devs)]];

    $vlanById = [];
    foreach ($vlans as $v) {
        $vlanById[$v['id']] = $v;
        $list = $byVlan[$v['id']] ?? [];
        $ds = expandIp((string)$v['dhcp_start'], $v['subnet']);
        $de = expandIp((string)$v['dhcp_end'], $v['subnet']);
        $hosts = vlanHostCount($v['subnet']);
        $r = ['v' => $v, 'hosts' => $hosts, 'online' => 0, 'used' => 0, 'new' => 0, 'nodesc' => 0,
              'dhcp_size' => ($ds && $de && ip2long($ds) !== false && ip2long($de) !== false) ? max(0, ip2long($de) - ip2long($ds) + 1) : 0,
              'dhcp_online' => 0, 'fix_online' => 0];
        foreach ($list as $d) {
            $on = (int)$d['online'] === 1;
            if ($on || $isDoc($d)) $r['used']++;
            if ($on) {
                $r['online']++;
                if (isIpInDhcp($d['ip'], $ds, $de)) $r['dhcp_online']++; else $r['fix_online']++;
                if (trim((string)$d['info']) === '') $r['nodesc']++;
            }
            if ((int)$d['is_new'] === 1) $r['new']++;
        }
        $r['free'] = max(0, $hosts - $r['used']);
        $r['pct']  = $hosts ? min(100, (int)round(100 * $r['used'] / $hosts)) : 0;
        $S['vlans'][] = $r;
        foreach (['hosts', 'online', 'used', 'new', 'nodesc', 'dhcp_size', 'dhcp_online'] as $k) $S['tot'][$k] += $r[$k];
    }
    $S['tot']['free'] = max(0, $S['tot']['hosts'] - $S['tot']['used']);
    $S['tot']['pct']  = $S['tot']['hosts'] ? min(100, (int)round(100 * $S['tot']['used'] / $S['tot']['hosts'])) : 0;

    // Zuletzt gesehen (Verteilung)
    $buckets = ['Letzte Stunde' => 0, 'Letzte 24 Stunden' => 0, 'Letzte 7 Tage' => 0, 'Letzte 30 Tage' => 0, 'Älter als 30 Tage' => 0, 'Nie gesehen' => 0];
    $vendors = [];
    $macs = [];
    $names = [];
    $withMac = $private = $documented = 0;
    $longOffline = [];
    foreach ($devs as $d) {
        $ls = trim((string)$d['last_seen']) !== '' ? strtotime($d['last_seen']) : false;
        if (!$ls) $buckets['Nie gesehen']++;
        else {
            $age = $now - $ls;
            if ($age <= 3600) $buckets['Letzte Stunde']++;
            elseif ($age <= 86400) $buckets['Letzte 24 Stunden']++;
            elseif ($age <= 7 * 86400) $buckets['Letzte 7 Tage']++;
            elseif ($age <= 30 * 86400) $buckets['Letzte 30 Tage']++;
            else $buckets['Älter als 30 Tage']++;
            if ((int)$d['online'] === 0 && $age > $offlineDays * 86400) $longOffline[] = $d + ['age_days' => (int)floor($age / 86400)];
        }
        if ($isDoc($d)) $documented++;
        $mac = trim((string)$d['mac']);
        if ($mac !== '') {
            $withMac++;
            $macs[strtoupper($mac)][] = $d['ip'];
            $v = trim((string)$d['vendor']);
            if ($v === 'Zufällige MAC (privat)') $private++;
            $vendors[$v !== '' ? $v : 'Unbekannt'] = ($vendors[$v !== '' ? $v : 'Unbekannt'] ?? 0) + 1;
        }
        $hn = mb_strtolower(trim((string)$d['hostname']));
        if ($hn !== '') $names[$hn][] = $d['ip'];
    }
    arsort($vendors);
    $S['buckets'] = $buckets;
    $S['vendors'] = array_slice($vendors, 0, 10, true);
    $S['withMac'] = $withMac;
    $S['private'] = $private;
    $S['documented'] = $documented;
    $S['dupMacs'] = array_filter($macs, fn($l) => count($l) > 1);
    $S['dupNames'] = array_filter($names, fn($l) => count($l) > 1);
    usort($longOffline, fn($a, $b) => $b['age_days'] <=> $a['age_days']);
    $S['longOffline'] = array_slice($longOffline, 0, 8);

    // Neueste Geräte
    $newest = array_filter($devs, fn($d) => trim((string)$d['first_seen']) !== '');
    usort($newest, fn($a, $b) => strcmp($b['first_seen'], $a['first_seen']));
    $S['newest'] = array_slice($newest, 0, 8);
    $S['new7'] = count(array_filter($newest, fn($d) => strtotime($d['first_seen']) >= $now - 7 * 86400));

    // Bereiche
    foreach ($ranges as $rg) {
        $v = $vlanById[$rg['vlan_id']] ?? null;
        if (!$v) continue;
        $s = ip2long($rg['start_ip']);
        $e = ip2long($rg['end_ip']);
        if ($s === false || $e === false) continue;
        $size = max(0, $e - $s + 1);
        $on = $used = 0;
        foreach ($byVlan[$v['id']] ?? [] as $d) {
            $n = ip2long($d['ip']);
            if ($n < $s || $n > $e) continue;
            if ((int)$d['online'] === 1) $on++;
            if ((int)$d['online'] === 1 || $isDoc($d)) $used++;
        }
        $S['ranges'][] = ['range' => $rg, 'vlan' => $v, 'size' => $size, 'online' => $on, 'used' => $used,
                          'pct' => $size ? min(100, (int)round(100 * $used / $size)) : 0];
    }

    // Verlauf: Online-Geräte pro Tag (Summe der Tageshöchstwerte je VLAN), letzte 30 Tage
    $rows = $db->query("SELECT d, SUM(m) AS total FROM (
            SELECT substr(ts,1,10) AS d, vlan_id, MAX(online) AS m FROM scan_log GROUP BY d, vlan_id
        ) GROUP BY d ORDER BY d DESC LIMIT 30")->fetchAll(PDO::FETCH_ASSOC);
    $daily = [];
    foreach (array_reverse($rows) as $r) $daily[$r['d']] = (int)$r['total'];
    $S['daily'] = $daily;
    $log = $db->query("SELECT COUNT(*) AS c, MIN(ts) AS first, MAX(ts) AS last, AVG(online) AS avg FROM scan_log")->fetch(PDO::FETCH_ASSOC);
    $S['log'] = $log;
    return $S;
}

function barRows(array $items, string $color = '#2f6fdb'): string {
    if (!$items) return '<div class="text-muted small">Keine Daten.</div>';
    $max = max(1, max($items));
    $out = '';
    foreach ($items as $label => $val) {
        $w = round(100 * $val / $max);
        $out .= '<div class="hbar"><div class="hbar-l" title="' . h($label) . '">' . h($label) . '</div>'
              . '<div class="hbar-t"><div class="hbar-f" style="width:' . $w . '%;background:' . $color . '"></div></div>'
              . '<div class="hbar-v">' . (int)$val . '</div></div>';
    }
    return $out;
}

function svgBars(array $data): string {
    if (!$data) return '<div class="text-muted small">Noch keine Verlaufsdaten – sie entstehen mit jedem Scan.</div>';
    $max = max(1, max($data));
    $n = count($data);
    $w = 640; $base = 140; $pad = 12;
    $step = ($w - 2 * $pad) / $n;
    $bw = max(4, $step - 5);
    $every = max(1, (int)ceil($n / 10));
    $out = '<svg viewBox="0 0 640 165" class="w-100" role="img" aria-label="Online-Geräte pro Tag">';
    $out .= '<line x1="' . $pad . '" y1="' . $base . '" x2="' . ($w - $pad) . '" y2="' . $base . '" stroke="#ced4da"/>';
    $i = 0;
    foreach ($data as $label => $val) {
        $bh = max(2, ($base - 18) * $val / $max);
        $x = $pad + $i * $step + ($step - $bw) / 2;
        $out .= sprintf('<rect x="%.1f" y="%.1f" width="%.1f" height="%.1f" rx="3" fill="#2f6fdb"><title>%s: %d online</title></rect>',
                        $x, $base - $bh, $bw, $bh, h(substr($label, 8, 2) . '.' . substr($label, 5, 2) . '.' . substr($label, 0, 4)), $val);
        if ($i % $every === 0) {
            $out .= sprintf('<text x="%.1f" y="158" font-size="10" text-anchor="middle" fill="#6c757d">%s</text>',
                            $x + $bw / 2, h(substr($label, 8, 2) . '.' . substr($label, 5, 2) . '.'));
        }
        if ($n <= 20) $out .= sprintf('<text x="%.1f" y="%.1f" font-size="10" text-anchor="middle" fill="#212529">%d</text>', $x + $bw / 2, $base - $bh - 4, $val);
        $i++;
    }
    return $out . '</svg>';
}

