function validateVlanInput(array $in): array {
    $vid = filter_var($in['vlan_id'] ?? '', FILTER_VALIDATE_INT, ['options' => ['min_range' => 1, 'max_range' => 4094]]);
    $name = trim($in['name'] ?? '');
    $cidr = parseCidr($in['subnet'] ?? '');
    $subnetIn = trim($in['subnet'] ?? '');
    $ds = expandIp($in['dhcp_start'] ?? '', $subnetIn);
    $de = expandIp($in['dhcp_end'] ?? '', $subnetIn);
    if ($vid === false) return [null, 'VLAN-ID muss zwischen 1 und 4094 liegen.'];
    if ($name === '') return [null, 'Bitte einen Namen angeben.'];
    if (!$cidr) return [null, 'Subnetz ungültig. Format: 192.168.10.0/24 (erlaubt: /22 bis /30).'];
    foreach ([$ds, $de] as $ip) {
        if ($ip !== '' && !filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4)) return [null, "DHCP-Adresse '$ip' ist ungültig."];
    }
    if (($ds === '') !== ($de === '')) return [null, 'DHCP-Start und -Ende müssen beide gesetzt oder beide leer sein.'];
    if ($ds !== '' && ip2long($ds) > ip2long($de)) return [null, 'DHCP-Start liegt hinter dem DHCP-Ende.'];
    return [[$vid, $name, long2ip($cidr[0]) . '/' . $cidr[1], $ds, $de], null];
}

function validateRangeInput(array $in, array $vlan): array {
    $name = mb_substr(trim($in['name'] ?? ''), 0, 40);
    if ($name === '') $name = 'Bereich';
    $s = expandIp($in['start_ip'] ?? '', $vlan['subnet']);
    $e = expandIp($in['end_ip'] ?? '', $vlan['subnet']);
    $color = $in['color'] ?? '';
    if (!filter_var($s, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4) || !filter_var($e, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4)) return [null, 'Start- und Ende-IP des Bereichs müssen gültige IPv4-Adressen sein (oder nur die letzte Zahl, z. B. 50).'];
    $p = parseCidr($vlan['subnet']);
    $first = $p[0] + 1;
    $last = $p[0] + (1 << (32 - $p[1])) - 2;
    if (ip2long($s) < $first || ip2long($e) > $last) return [null, 'Der Bereich muss innerhalb des Subnetzes ' . $vlan['subnet'] . ' liegen.'];
    if (ip2long($s) > ip2long($e)) return [null, 'Der Start des Bereichs liegt hinter dem Ende.'];
    if ($color === '' || !isset(COLORS[$color])) return [null, 'Bitte eine Farbe wählen.'];
    return [[$name, $s, $e, $color], null];
}

// ---- AJAX (Inline-Bearbeitung, Auto-Scan-Tick)
if (isset($_POST['ajax'])) {
    header('Content-Type: application/json; charset=utf-8');
    if (!hash_equals($csrf, $_POST['csrf'] ?? '')) { http_response_code(403); echo json_encode(['ok' => false, 'error' => 'Ungültiges Token, bitte Seite neu laden.']); exit; }

    if ($_POST['action'] === 'tick') {
        session_write_close();
        ignore_user_abort(true);
        $ran = runDueScan($db);
        echo json_encode(['ok' => true, 'ran' => $ran, 'last' => (int)getSetting($db, 'last_scan_all', 0)]);
        exit;
    }

    if ($_POST['action'] === 'ack') {
        $ip = $_POST['ip'] ?? '';
        if (!filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4)) { echo json_encode(['ok' => false, 'error' => 'Ungültige IP.']); exit; }
        $db->prepare("UPDATE devices SET is_new=0 WHERE ip=?")->execute([$ip]);
        echo json_encode(['ok' => true]);
        exit;
    }

    if ($_POST['action'] === 'save_field') {
        $field = $_POST['field'] ?? '';
        $value = trim($_POST['value'] ?? '');
        $ip = $_POST['ip'] ?? '';
        $vlanId = (int)($_POST['vlan_id'] ?? 0);
        if (!in_array($field, ['hostname', 'mac', 'info', 'color'], true) || !filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4) || !$vlanId) {
            echo json_encode(['ok' => false, 'error' => 'Ungültige Eingabe.']); exit;
        }
        if ($field === 'color' && !isset(COLORS[$value])) { echo json_encode(['ok' => false, 'error' => 'Unbekannte Farbe.']); exit; }
        $now = date('Y-m-d H:i:s');
        $out = ['ok' => true];
        // Eine Beschreibung bestätigt einen neu erkannten Client
        $clear = ($field === 'info' && $value !== '');
        $extra = $clear ? ', is_new=0' : '';
        $keepFirst = "first_seen=CASE WHEN IFNULL(devices.first_seen,'')='' THEN excluded.first_seen ELSE devices.first_seen END";
        if ($field === 'mac') {
            $value = normalizeMac($value);
            $out['mac'] = $value;
            $out['vendor'] = macVendor($value);
            $db->prepare("INSERT INTO devices (ip, vlan_id, mac, vendor, first_seen) VALUES (?, ?, ?, ?, ?)
                ON CONFLICT(ip) DO UPDATE SET mac=excluded.mac, vendor=excluded.vendor, vlan_id=excluded.vlan_id, $keepFirst")
               ->execute([$ip, $vlanId, $value, $out['vendor'], $now]);
        } else {
            $db->prepare("INSERT INTO devices (ip, vlan_id, $field, first_seen) VALUES (?, ?, ?, ?)
                ON CONFLICT(ip) DO UPDATE SET $field=excluded.$field, vlan_id=excluded.vlan_id, $keepFirst$extra")
               ->execute([$ip, $vlanId, $value, $now]);
        }
        $out['new_cleared'] = $clear;
        echo json_encode($out);
        exit;
    }
    echo json_encode(['ok' => false, 'error' => 'Unbekannte Aktion.']);
    exit;
}

// ---- Normale Formular-Aktionen
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!hash_equals($csrf, $_POST['csrf'] ?? '')) { http_response_code(403); exit('Ungültiges CSRF-Token.'); }
    $action = $_POST['action'] ?? '';
    $vlanRowId = (int)($_POST['id'] ?? 0);
    $backPage = in_array($_POST['page'] ?? '', ['stats', 'settings'], true) ? $_POST['page'] : 'network';

    if ($action === 'add_vlan' || $action === 'update_vlan') {
        [$data, $err] = validateVlanInput($_POST);
        if ($err) { flash('danger', $err); redirect($vlanRowId ?: null); }
        if ($action === 'add_vlan') {
            $db->prepare("INSERT INTO vlans (vlan_id, name, subnet, dhcp_start, dhcp_end) VALUES (?, ?, ?, ?, ?)")->execute($data);
            $vlanRowId = (int)$db->lastInsertId();
            flash('success', 'VLAN angelegt.');
        } else {
            $db->prepare("UPDATE vlans SET vlan_id=?, name=?, subnet=?, dhcp_start=?, dhcp_end=? WHERE id=?")->execute([...$data, $vlanRowId]);
            flash('success', 'VLAN aktualisiert.');
        }
        redirect($vlanRowId);
    }

    if ($action === 'delete_vlan') {
        $db->beginTransaction();
        $db->prepare("DELETE FROM devices WHERE vlan_id=?")->execute([$vlanRowId]);
        $db->prepare("DELETE FROM ranges WHERE vlan_id=?")->execute([$vlanRowId]);
        $db->prepare("DELETE FROM scan_log WHERE vlan_id=?")->execute([$vlanRowId]);
        $db->prepare("DELETE FROM vlans WHERE id=?")->execute([$vlanRowId]);
        $db->commit();
        flash('success', 'VLAN mit Geräten und Farbbereichen gelöscht.');
        redirect();
    }

    if ($action === 'save_range' || $action === 'delete_range') {
        $rangeId = (int)($_POST['range_id'] ?? 0);
        $s = $db->prepare("SELECT * FROM vlans WHERE id=?");
        $s->execute([$vlanRowId]);
        $v = $s->fetch(PDO::FETCH_ASSOC);
        if (!$v) { flash('danger', 'VLAN nicht gefunden.'); redirect(); }
        if ($action === 'delete_range') {
            $db->prepare("DELETE FROM ranges WHERE id=? AND vlan_id=?")->execute([$rangeId, $vlanRowId]);
            flash('success', 'Farbbereich gelöscht.');
        } else {
            [$data, $err] = validateRangeInput($_POST, $v);
            if ($err) { flash('danger', $err); redirect($vlanRowId); }
            if ($rangeId) {
                $db->prepare("UPDATE ranges SET name=?, start_ip=?, end_ip=?, color=? WHERE id=? AND vlan_id=?")->execute([...$data, $rangeId, $vlanRowId]);
                flash('success', 'Farbbereich aktualisiert.');
            } else {
                $db->prepare("INSERT INTO ranges (vlan_id, name, start_ip, end_ip, color) VALUES (?, ?, ?, ?, ?)")->execute([$vlanRowId, ...$data]);
                flash('success', 'Farbbereich angelegt.');
            }
        }
        redirect($vlanRowId);
    }

    if ($action === 'run_scan') {
        set_time_limit(0);
        $s = $db->prepare("SELECT * FROM vlans WHERE id=?");
        $s->execute([$vlanRowId]);
        $v = $s->fetch(PDO::FETCH_ASSOC);
        $n = $v ? scanVlan($db, $v) : -1;
        if ($n < 0) flash('danger', 'Scan fehlgeschlagen. Ist nmap installiert und für PHP aufrufbar?');
        else flash('success', "Scan beendet: $n Geräte online, davon {$GLOBALS['scanStats']['macs']} mit MAC. ARP-Einträge auf dem Server: {$GLOBALS['scanStats']['arp']}. Herstellerliste: " . (ouiAvailable() ? 'gefunden' : 'NICHT gefunden') . '.');
        redirect($vlanRowId);
    }

    if ($action === 'run_scan_all') {
        scanAll($db);
        flash('success', 'Alle VLANs gescannt.');
        redirect($vlanRowId ?: null, $backPage);
    }

    if ($action === 'save_settings') {
        setSetting($db, 'scan_interval', max(0, min(10080, (int)($_POST['scan_interval'] ?? 0))));
        setSetting($db, 'flag_new', isset($_POST['flag_new']) ? '1' : '0');
        setSetting($db, 'offline_days', max(1, min(365, (int)($_POST['offline_days'] ?? 30))));
        setSetting($db, 'log_days', max(7, min(730, (int)($_POST['log_days'] ?? 90))));
        flash('success', 'Einstellungen gespeichert.');
        redirect(null, 'settings');
    }
    redirect();
}

// ---- Daten laden
$page = in_array($_GET['page'] ?? '', ['stats', 'settings'], true) ? $_GET['page'] : 'network';
$vlans = $db->query("SELECT * FROM vlans ORDER BY vlan_id ASC")->fetchAll(PDO::FETCH_ASSOC);
$selectedVlan = (int)($_GET['vlan'] ?? ($vlans[0]['id'] ?? 0));
$currentVlan = null;
foreach ($vlans as $v) if ((int)$v['id'] === $selectedVlan) { $currentVlan = $v; break; }
if (!$currentVlan && $vlans) { $currentVlan = $vlans[0]; $selectedVlan = (int)$currentVlan['id']; }
if ($currentVlan) {
    foreach (['dhcp_start', 'dhcp_end'] as $k) $currentVlan[$k] = expandIp((string)$currentVlan[$k], $currentVlan['subnet']);
}

// Zähler je VLAN (online / neu) für die VLAN-Auswahl und das Hinweisbanner
$vlanCounts = [];
foreach ($db->query("SELECT vlan_id, SUM(online) AS o, SUM(is_new) AS n FROM devices GROUP BY vlan_id")->fetchAll(PDO::FETCH_ASSOC) as $r) {
    $vlanCounts[(int)$r['vlan_id']] = ['o' => (int)$r['o'], 'n' => (int)$r['n']];
}
$totalNew = array_sum(array_column($vlanCounts, 'n'));

$devices = [];
$ranges = [];
$rangeCalc = [];
$onlineCount = 0;
$newCount = 0;
if ($page === 'network' && $currentVlan) {
    $s = $db->prepare("SELECT * FROM devices WHERE vlan_id=?");
    $s->execute([$currentVlan['id']]);
    foreach ($s->fetchAll(PDO::FETCH_ASSOC) as $d) {
        $devices[$d['ip']] = $d;
        $onlineCount += (int)$d['online'];
        $newCount += (int)$d['is_new'];
    }
    $s = $db->prepare("SELECT * FROM ranges WHERE vlan_id=?");
    $s->execute([$currentVlan['id']]);
    $ranges = $s->fetchAll(PDO::FETCH_ASSOC);
    foreach ($ranges as &$rg) if (!isset(COLORS[$rg['color']]) || $rg['color'] === '') $rg['color'] = 'gray';
    unset($rg);
    usort($ranges, fn($a, $b) => ip2long($a['start_ip']) <=> ip2long($b['start_ip']));
    foreach ($ranges as $rg) $rangeCalc[] = ['r' => $rg, 's' => (int)ip2long($rg['start_ip']), 'e' => (int)ip2long($rg['end_ip'])];
    usort($rangeCalc, fn($a, $b) => ($a['e'] - $a['s']) <=> ($b['e'] - $b['s']));
}

