                <button type="submit" class="btn btn-primary">Speichern</button>
            </div>
        </form>
    </div>
</div>

<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script>
<script>
const CSRF = <?= json_encode($csrf) ?>;
const COLORS = <?= json_encode($colorMap) ?>;
const VLAN_ROW_ID = <?= (int)($currentVlan['id'] ?? 0) ?>;
let lastScan = <?= $lastAll ?>;

function post(data) {
    const fd = new FormData();
    fd.append('ajax', '1');
    fd.append('csrf', CSRF);
    Object.entries(data).forEach(([k, v]) => fd.append(k, v));
    return fetch(location.pathname, { method: 'POST', body: fd }).then(r => r.json());
}

// ---- VLAN-Modal: Neu / Bearbeiten
document.getElementById('vlanModal').addEventListener('show.bs.modal', e => {
    const raw = e.relatedTarget && e.relatedTarget.dataset.vlan;
    const v = raw ? JSON.parse(raw) : null;
    document.getElementById('vm-title').textContent = v ? 'VLAN bearbeiten' : 'Neues VLAN';
    document.getElementById('vm-action').value = v ? 'update_vlan' : 'add_vlan';
    document.getElementById('vm-id').value = v ? v.id : '';
    ['vlan_id', 'name', 'subnet', 'dhcp_start', 'dhcp_end'].forEach(f =>
        document.getElementById('vm-' + f).value = v ? (v[f] ?? '') : '');
});

// ---- Einstellungen: Schnellwahl fürs Intervall
document.querySelectorAll('[data-preset]').forEach(b => b.addEventListener('click', () => {
    document.getElementById('scan_interval').value = b.dataset.preset;
}));

// ---- "NEU"-Markierung entfernen
function clearNew(tr) {
    tr.dataset.new = '0';
    tr.querySelector('[data-ack]')?.remove();
    const a = tr.dataset.accent;
    tr.firstElementChild.style.boxShadow = a ? 'inset 4px 0 0 ' + a : '';
    applyFilter();
}
document.querySelectorAll('[data-ack]').forEach(b => b.addEventListener('click', () => {
    const tr = b.closest('tr');
    post({ action: 'ack', ip: tr.dataset.ip }).then(res => { if (res.ok) clearNew(tr); });
}));

// ---- Direktes Bearbeiten: speichert beim Verlassen des Feldes
document.querySelectorAll('.cell-input').forEach(input => {
    input.addEventListener('change', () => {
        const tr = input.closest('tr');
        post({ action: 'save_field', ip: tr.dataset.ip, vlan_id: VLAN_ROW_ID, field: input.dataset.field, value: input.value })
            .then(res => {
                if (!res.ok) { alert(res.error || 'Speichern fehlgeschlagen.'); return; }
                if (input.dataset.field === 'mac') {
                    input.value = res.mac;
                    const v = tr.querySelector('.vendor');
                    v.textContent = v.title = res.vendor || '';
                }
                if (res.new_cleared) clearNew(tr);
                tr.dataset.used = '1';
                input.classList.add('saved');
                setTimeout(() => input.classList.remove('saved'), 900);
            })
            .catch(() => alert('Verbindung fehlgeschlagen.'));
    });
});

// ---- Zeilenfarbe
const palette = document.getElementById('palette');
let paletteRow = null;
document.querySelectorAll('.color-btn').forEach(btn => btn.addEventListener('click', e => {
    e.stopPropagation();
    paletteRow = btn.closest('tr');
    const r = btn.getBoundingClientRect();
    palette.style.display = 'grid';
    palette.style.top = Math.min(r.bottom + 4, window.innerHeight - palette.offsetHeight - 8) + 'px';
    palette.style.left = Math.max(8, r.right - palette.offsetWidth) + 'px';
}));
palette?.addEventListener('click', e => {
    const sw = e.target.closest('[data-color]');
    if (!sw || !paletteRow) return;
    const key = sw.dataset.color, tr = paletteRow, hex = COLORS[key];
    post({ action: 'save_field', ip: tr.dataset.ip, vlan_id: VLAN_ROW_ID, field: 'color', value: key }).then(res => {
        if (!res.ok) { alert(res.error); return; }
        const bg = hex || tr.dataset.defbg;   // ohne eigene Farbe gilt Bereichs- bzw. DHCP-Farbe
        bg ? tr.style.setProperty('--bs-table-bg', bg) : tr.style.removeProperty('--bs-table-bg');
        tr.querySelector('.color-btn').style.background = hex || '#fff';
    });
    palette.style.display = 'none';
});
document.addEventListener('click', () => { if (palette) palette.style.display = 'none'; });
document.querySelector('.table-wrap')?.addEventListener('scroll', () => { if (palette) palette.style.display = 'none'; });

// ---- Filter
function applyFilter() {
    const q = (document.getElementById('filter')?.value || '').toLowerCase();
    const only = document.getElementById('onlyUsed')?.checked;
    const onlyNew = document.getElementById('onlyNew')?.checked;
    document.querySelectorAll('.ip-table tbody tr').forEach(tr => {
        const text = tr.dataset.ip + ' ' + [...tr.querySelectorAll('input')].map(i => i.value).join(' ') + ' ' + tr.querySelector('.vendor').textContent;
        const show = (!only || tr.dataset.used === '1') && (!onlyNew || tr.dataset.new === '1') && text.toLowerCase().includes(q);
        tr.style.display = show ? '' : 'none';
    });
}
document.getElementById('filter')?.addEventListener('input', applyFilter);
document.getElementById('onlyUsed')?.addEventListener('change', applyFilter);
document.getElementById('onlyNew')?.addEventListener('change', applyFilter);
if (new URLSearchParams(location.search).get('new') === '1' && document.getElementById('onlyNew')) {
    document.getElementById('onlyNew').checked = true;
    applyFilter();
}

// ---- Auto-Scan-Tick (alle 60 s) + Seite aktualisieren, wenn ein neuer Scan vorliegt
setInterval(() => {
    post({ action: 'tick' }).then(res => {
        if (!res.ok || res.last === lastScan) return;
        lastScan = res.last;
        const a = document.activeElement;
        const busy = a && ['INPUT', 'SELECT', 'TEXTAREA'].includes(a.tagName) && a.id !== 'filter';
        if (!busy && !document.querySelector('.modal.show')) location.reload();
    }).catch(() => {});
}, 60000);
</script>
</body>
</html>
